<body>
<h1>CHIP-8 Emulator</h1>

<div class="container">
  <div class="emulator-section">
    <div class="display-area">
      <canvas id="display" width="640" height="320"></canvas>

      <div class="controls">
        <button id="runBtn" onclick="toggleRun()">Run</button>
        <button id="pauseBtn" onclick="pause()">Pause</button>
        <button id="stepBtn" onclick="singleStep()">Step</button>
        <button id="resetBtn" onclick="reset()">Reset</button>
        <div class="file-input-wrapper">
          <button id="loadBtn">Load ROM</button>
          <input type="file" id="fileInput" accept=".ch8,.rom,.hex" onchange="loadROMFile(event)">
        </div>
      </div>

      <div class="speed-control">
        <label>Instructions per frame:</label>
        <input type="range" id="speedSlider" min="1" max="12" value="6" oninput="updateSpeed()">
        <span id="speedValue">6</span>
      </div>

      <div class="keyboard" id="keyboard">
        <!-- Generated by JS -->
      </div>

      <div class="status" id="status">
        <span class="paused">Paused</span>
      </div>
    </div>

    <div class="info-panel">
      <h3>CHIP-8 Emulator</h3>
      <p><strong>Display:</strong> 64×32 pixels</p>
      <p><strong>Memory:</strong> 4 KB (0x000-0xFFF)</p>
      <p><strong>Registers:</strong> V0-VF (16 × 8-bit)</p>
      <p><strong>Index Register:</strong> I (16-bit)</p>
      <p><strong>Program Counter:</strong> PC (16-bit)</p>
      <p><strong>Timers:</strong> Delay & Sound (60 Hz countdown)</p>
      <p><strong>Stack:</strong> 16 levels deep</p>
      <p><strong>Font:</strong> Loaded at 0x050</p>
      <p><strong>Programs:</strong> Load at 0x200</p>
    </div>
  </div>

  <div class="debugger">
