<script>
// CHIP-8 Emulator Implementation

const FONT_SET = [
  0xF0, 0x90, 0x90, 0x90, 0xF0, // 0
  0x20, 0x60, 0x20, 0x20, 0x70, // 1
  0xF0, 0x10, 0xF0, 0x80, 0xF0, // 2
  0xF0, 0x10, 0xF0, 0x10, 0xF0, // 3
  0x90, 0x90, 0xF0, 0x10, 0x10, // 4
  0xF0, 0x80, 0xF0, 0x10, 0xF0, // 5
  0xF0, 0x80, 0xF0, 0x90, 0xF0, // 6
  0xF0, 0x10, 0x20, 0x40, 0x40, // 7
  0xF0, 0x90, 0xF0, 0x90, 0xF0, // 8
  0xF0, 0x90, 0xF0, 0x10, 0xF0, // 9
  0xF0, 0x90, 0xF0, 0x90, 0x90, // A
  0xE0, 0x90, 0xE0, 0x90, 0xE0, // B
  0xF0, 0x80, 0x80, 0x80, 0xF0, // C
  0xE0, 0x90, 0x90, 0x90, 0xE0, // D
  0xF0, 0x80, 0xF0, 0x80, 0xF0, // E
  0xF0, 0x80, 0xF0, 0x80, 0x80  // F
];

// Keypad mapping: CHIP-8 key -> keyboard key
const KEY_MAP = {
  0: 'KeyX',
  1: 'Key1',
  2: 'Key2',
  3: 'Key3',
  4: 'KeyQ',
  5: 'KeyW',
  6: 'KeyE',
  7: 'KeyA',
  8: 'KeyS',
  9: 'KeyD',
  10: 'KeyZ',
  11: 'KeyC',
  12: 'Key4',
  13: 'KeyR',
  14: 'KeyF',
  15: 'KeyV'
};

const CHIP8_KEYS = [
  ['X', '1', '2', '3'],
  ['Q', 'W', 'E', 'A'],
  ['S', 'D', 'Z', 'C'],
  ['4', 'R', 'F', 'V']
];

class Chip8 {
  constructor() {
    this.memory = new Uint8Array(4096);
    this.V = new Uint8Array(16);
    this.I = 0;
    this.pc = 0x200;
    this.stack = [];
    this.sp = 0;
    this.delayTimer = 0;
    this.soundTimer = 0;
    this.display = new Uint8Array(64 * 32);
    this.keys = new Uint8Array(16);
    this opcode = 0;
    this.currentInstruction = null;
    this.running = false;

    // Load font set
    this.loadFontSet();

    // Initialize display
    this.initDisplay();
  }

  loadFontSet() {
    for (let i = 0; i < FONT_SET.length; i++) {
      this.memory[0x050 + i] = FONT_SET[i];
    }
  }

  initDisplay() {
    const canvas = document.getElementById('display');
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }

  loadROM(romData) {
    // Clear memory first
    this.memory.fill(0);
    this.loadFontSet();

    // Load ROM at 0x200
    for (let i = 0; i < romData.length; i++) {
      this.memory[0x200 + i] = romData[i];
    }

    // Reset state
    this.pc = 0x200;
    this.I = 0;
    this.V.fill(0);
    this.stack = [];
    this.sp = 0;
    this.delayTimer = 0;
    this.soundTimer = 0;
    this.display.fill(0);
    this.keys.fill(0);

    this.initDisplay();
    this.updateDebugger();
  }

  fetchOpcode() {
    this.opcode = (this.memory[this.pc] << 8) | this.memory[this.pc + 1];
    this.pc += 2;
    return this.opcode;
  }

  decodeAndExecute(opcode) {
    const x = (opcode & 0x0F00) >> 8;
    const y = (opx & 0x00F0) >> 4;
    const n = opcode & 0x000F;
    const nn = opcode & 0x00FF;
    const nnn = opcode & 0x0FFF;
    const kk = opcode & 0x00FF;

    let mnemonic = '';

    switch (opcode & 0xF000) {
      case 0x0000:
        switch (opcode) {
          case 0x00E0:
            // 00E0: Clear display
            this.display.fill(0);
            this.initDisplay();
            mnemonic = 'CLS';
            break;
          case 0x00EE:
            // 00EE: Return from subroutine
            if (this.sp > 0) {
              this.sp--;
              this.pc = this.stack[this.sp];
            }
            mnemonic = 'RET';
            break;
          default:
            mnemonic = 'UNKNOWN_0x0000';
        }
        break;

      case 0x1000:
        // 1NNN: Jump to address NNN
        this.pc = nnn;
        mnemonic = `JP ${this.hex(nnn)}`;
        break;

      case 0x2000:
        // 2NNN: Call subroutine at NNN
        this.stack[this.sp] = this.pc;
        this.sp++;
        this.pc = nnn;
        mnemonic = `CALL ${this.hex(nnn)}`;
        break;

      case 0x3000:
        // 3XNN: Skip next instruction if VX == NN
        if (this.V[x] === kk) {
          this.pc += 2;
        }
        mnemonic = `SE V${this.hex(x)}, ${this.hex(kk)}`;
        break;

      case 0x4000:
        // 4XNN: Skip next instruction if VX != NN
        if (this.V[x] !== kk) {
          this.pc += 2;
        }
        mnemonic = `SNE V${this.hex(x)}, ${this.hex(kk)}`;
        break;

      case 0x5000:
        // 5XY0: Skip next instruction if VX == VY
        if (this.V[x] === this.V[y]) {
          this.pc += 2;
        }
        mnemonic = `SE V${this.hex(x)}, V${this.hex(y)}`;
        break;

      case 0x6000:
        // 6XNN: Set VX to NN
        this.V[x] = kk;
        mnemonic = `LD V${this.hex(x)}, ${this.hex(kk)}`;
        break;

      case 0x7000:
        // 7XNN: Add NN to VX
        this.V[x] = (this.V[x] + kk) & 0xFF;
        mnemonic = `ADD V${this.hex(x)}, ${this.hex(kk)}`;
        break;

      case 0x8000:
        switch (n) {
          case 0x0:
            // 8XY0: Set VX to VY
            this.V[x] = this.V[y];
            mnemonic = `LD V${this.hex(x)}, V${this.hex(y)}`;
            break;
          case 0x1:
            // 8XY1: Set VX to VX OR VY
            this.V[x] |= this.V[y];
            mnemonic = `OR V${this.hex(x)}, V${this.hex(y)}`;
            break;
          case 0x2:
            // 8XY2: Set VX to VX AND VY
            this.V[x] &= this.V[y];
            mnemonic = `AND V${this.hex(x)}, V${this.hex(y)}`;
            break;
          case 0x3:
            // 8XY3: Set VX to VX XOR VY
            this.V[x] ^= this.V[y];
            mnemonic = `XOR V${this.hex(x)}, V${this.hex(y)}`;
            break;
          case 0x4:
            // 8XY4: Add VY to VX, set VF to carry
            const sum = this.V[x] + this.V[y];
            this.V[0xF] = sum > 0xFF ? 1 : 0;
            this.V[x] = sum & 0xFF;
            mnemonic = `ADD V${this.hex(x)}, V${this.hex(y)}`;
            break;
          case 0x5:
            // 8XY5: Subtract VY from VX, set VF to NOT borrow
            this.V[0xF] = this.V[x] > this.V[y] ? 1 : 0;
            this.V[x] = (this.V[x] - this.V[y]) & 0xFF;
            mnemonic = `SUB V${this.hex(x)}, V${this.hex(y)}`;
            break;
          case 0x6:
            // 8XY6: Shift VX right by 1, set VF to least significant bit
            this.V[0xF] = this.V[x] & 0x1;
            this.V[x] = this.V[x] >> 1;
            mnemonic = `SHR V${this.hex(x)}, V${this.hex(y)}`;
            break;
          case 0x7:
            // 8XY7: Subtract VX from VY, set VF to NOT borrow
            this.V[0xF] = this.V[y] > this.V[x] ? 1 : 0;
            this.V[x] = (this.V[y] - this.V[x]) & 0xFF;
            mnemonic = `SUBN V${this.hex(x)}, V${this.hex(y)}`;
            break;
          case 0x8:
            // 8XY8: Shift VX left by 1, set VF to most significant bit
            this.V[0xF] = (this.V[x] & 0x80) >> 7;
            this.V[x] = (this.V[x] << 1) & 0xFF;
            mnemonic = `SHL V${this.hex(x)}, V${this.hex(y)}`;
            break;
          case 0x9:
            // 8XY9: Skip if VX != VY
            if (this.V[x] !== this.V[y]) {
              this.pc += 2;
            }
            mnemonic = `SNE V${this.hex(x)}, V${this.hex(y)}`;
            break;
          default:
            mnemonic = 'UNKNOWN_8XYN';
        }
        break;

      case 0x9000:
        // 9XY0: Skip next instruction if VX != VY
        if (this.V[x] !== this.V[y]) {
          this.pc += 2;
        }
        mnemonic = `SNE V${this.hex(x)}, V${this.hex(y)}`;
        break;

      case 0xA000:
        // ANNN: Set I to NNN
        this.I = nnn;
        mnemonic = `LD I, ${this.hex(nnn)}`;
        break;

      case 0xB000:
        // BNNN: Jump to address NNN + V0
        this.pc = nnn + this.V[0];
        mnemonic = `JP V0, ${this.hex(nnn)}`;
        break;

      case 0xC000:
        // CXNN: Set VX to random byte AND NN
        this.V[x] = Math.floor(Math.random() * 256) & kk;
        mnemonic = `RND V${this.hex(x)}, ${this.hex(kk)}`;
        break;

      case 0xD000:
        // DXYN: Draw sprite at (VX, VY) with N bytes
        const spriteX = this.V[x];
        const spriteY = this.V[y];
        const height = n;
        let collision = 0;

        for (let row = 0; row < height; row++) {
          const spriteByte = this.memory[this.I + row];
          for (let col = 0; col < 8; col++) {
            const pixel = (spriteByte & (0x80 >> col)) !== 0;
            const idx = ((spriteY + row) % 32) * 64 + ((spriteX + col) % 64);

            if (pixel !== (this.display[idx] & 1)) {
              collision = 1;
            }

            this.display[idx] ^= pixel;
          }
        }

        this.V[0xF] = collision;
        this.drawDisplay();
        mnemonic = `DRW V${this.hex(x)}, V${this.hex(y)}, ${height}`;
        break;

      case 0xE000:
        switch (kk) {
          case 0x9E:
            // EX9E: Skip if key in VX is pressed
            if (this.keys[this.V[x]] !== 0) {
              this.pc += 2;
            }
            mnemonic = `SKP V${this.hex(x)}`;
            break;
          case 0xA1:
            // EXA1: Skip if key in VX is not pressed
            if (this.keys[this.V[x]] === 0) {
              this.pc += 2;
            }
            mnemonic = `SKNP V${this.hex(x)}`;
            break;
          default:
            mnemonic = 'UNKNOWN_EXNN';
        }
        break;

      case 0xF000:
        switch (n) {
          case 0x0:
            // FX00: Set VX to delay timer value
            this.V[x] = this.delayTimer;
            mnemonic = `LD V${this.hex(x)}, DT`;
            break;
          case 0x1:
            // FX07: Set VX to delay timer value
            this.V[x] = this.delayTimer;
            mnemonic = `LD V${this.hex(x)}, DT`;
            break;
          case 0x2:
            // FX0A: Wait for key press, store in VX
            {
              let keyFound = false;
              for (let i = 0; i < 16; i++) {
                if (this.keys[i] !== 0) {
                  this.V[x] = i;
                  keyFound = true;
                  break;
                }
              }
              if (!keyFound) {
                this.pc -= 2; // Don't advance PC
              }
              mnemonic = `LD V${this.hex(x)}, K`;
            }
            break;
          case 0x3:
            // FX03: Store BCD of VX at I
            const bcd = this.V[x];
            this.memory[this.I] = Math.floor(bcd / 100);
            this.memory[this.I + 1] = Math.floor((bcd % 100) / 10);
            this.memory[this.I + 2] = bcd % 10;
            mnemonic = `BCD V${this.hex(x)}`;
            break;
          case 0x4:
            // FX04: Store registers V0-VX at I
            for (let i = 0; i <= x; i++) {
              this.memory[this.I + i] = this.V[i];
            }
            mnemonic = `LD [I], V${this.hex(x)}`;
            break;
          case 0x5:
            // FX05: Store registers V0-VX at I (alternative)
            for (let i = 0; i <= x; i++) {
              this.memory[this.I + i] = this.V[i];
            }
            mnemonic = `LD [I], V${this.hex(x)}`;
            break;
          case 0x6:
            // FX06: Store registers V0-VX at I (alternative)
            for (let i = 0; i <= x; i++) {
              this.memory[this.I + i] = this.V[i];
            }
            mnemonic = `LD [I], V${this.hex(x)}`;
            break;
          case 0x7:
            // FX07: Add delay timer to VX
            this.V[x] = (this.V[x] + this.delayTimer) & 0xFF;
            mnemonic = `ADD V${this.hex(x)}, DT`;
            break;
          case 0x8:
            // FX08: Set delay timer to VX
            this.delayTimer = this.V[x];
            mnemonic = `LD DT, V${this.hex(x)}`;
            break;
          case 0x9:
            // FX09: Set sound timer to VX
            this.soundTimer = this.V[x];
            mnemonic = `LD ST, V${this.hex(x)}`;
            break;
          case 0xA:
            // FX0A: Set I to address of sprite for character VX
            this.I = this.V[x] * 5;
            mnemonic = `LD F, V${this.hex(x)}`;
            break;
          case 0xB:
            // FX0B: Set I to address of sprite for character VX (alternative)
            this.I = this.V[x] * 5;
            mnemonic = `LD B, V${this.hex(x)}`;
            break;
          case 0xC:
            // FX0C: Store registers V0-VX at I (alternative)
            for (let i = 0; i <= x; i++) {
              this.memory[this.I + i] = this.V[i];
            }
            mnemonic = `LD [I], V${this.hex(x)}`;
            break;
          case 0xD:
            // FX0D: Store registers V0-VX at I (alternative)
            for (let i = 0; i <= x; i++) {
              this.memory[this.I + i] = this.V[i];
            }
            mnemonic = `LD [I], V${this.hex(x)}`;
            break;
          case 0xE:
            // FX0E: Store registers V0-VX at I (alternative)
            for (let i = 0; i <= x; i++) {
              this.memory[this.I + i] = this.V[i];
            }
            mnemonic = `LD [I], V${this.hex(x)}`;
            break;
          case 0xF:
            // FX0F: Store registers V0-VX at I (alternative)
            for (let i = 0; i <= x; i++) {
              this.memory[this.I + i] = this.V[i];
            }
            mnemonic = `LD [I], V${this.hex(x)}`;
            break;
          default:
            mnemonic = 'UNKNOWN_FXNN';
        }
        break;

      default:
        mnemonic = 'UNKNOWN';
    }

    this.currentInstruction = {
      opcode: opcode,
      mnemonic: mnemonic,
      x: x,
      y: y,
      n: n,
      nn: nn,
      nnn: nnn,
      kk: kk
    };
  }

  hex(val, digits = 2) {
    return '0x' + val.toString(16).toUpperCase().padStart(digits * 2, '0');
  }

  drawDisplay() {
    const canvas = document.getElementById('display');
    const ctx = canvas.getContext('2d');

    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#00ff88';
    for (let y = 0; y < 32; y++) {
      for (let x = 0; x < 64; x++) {
        if (this.display[y * 64 + x]) {
          ctx.fillRect(x * 10, y * 10, 10, 10);
        }
      }
    }
  }

  updateTimers() {
    if (this.delayTimer > 0) {
      this.delayTimer--;
    }
    if (this.soundTimer > 0) {
      this.soundTimer--;
    }
  }

  step() {
    if (!this.running) return;

    this.fetchOpcode();
    this.decodeAndExecute(this.opcode);
    this.updateTimers();
    this.updateDebugger();
  }

  run() {
    this.running = true;
    document.getElementById('status').innerHTML = '<span class="running">Running</span>';
    document.getElementById('runBtn').classList.add('active');
    document.getElementById('pauseBtn').classList.remove('active');
  }

  pause() {
    this.running = false;
    document.getElementById('status').innerHTML = '<span class="paused">Paused</span>';
    document.getElementById('runBtn').classList.remove('active');
    document.getElementById('pauseBtn').classList.add('active');
  }

  reset() {
    this.running = false;
    this.pc = 0x200;
    this.I = 0;
    this.V.fill(0);
    this.stack = [];
    this.sp = 0;
    this.delayTimer = 0;
    this.soundTimer = 0;
    this.display.fill(0);
    this.keys.fill(0);
    this.opcode = 0;
    this.currentInstruction = null;
    this.initDisplay();
    this.updateDebugger();
    document.getElementById('status').innerHTML = '<span class="paused">Paused</span>';
    document.getElementById('runBtn').classList.remove('active');
    document.getElementById('pauseBtn').classList.remove('active');
  }

  updateDebugger() {
    // Update registers
    for (let i = 0; i < 16; i++) {
      const regEl = document.getElementById(`regV${this.hex(i).replace('0x', '')}`);
      if (regEl) {
        regEl.textContent = this.hex(this.V[i], 1);
      }
    }

    // Update I register
    document.getElementById('indexReg').textContent = this.hex(this.I, 2);

    // Update PC
    document.getElementById('programCounter').textContent = this.hex(this.pc, 2);

    // Update stack
    const stackEl = document.getElementById('stack');
    if (this.sp === 0) {
      stackEl.innerHTML = '<span class="debug-stack-item">Empty</span>';
    } else {
      stackEl.innerHTML = this.stack.slice(0, this.sp).map(addr => 
        `<span class="debug-stack-item">${this.hex(addr, 2)}</span>`
      ).join('');
    }

    // Update timers
    document.getElementById('delayTimer').textContent = this.delayTimer;
    document.getElementById('soundTimer').textContent = this.soundTimer;

    // Update current instruction
    if (this.currentInstruction) {
      document.getElementById('currentOpcode').textContent = this.hex(this.opcode, 2);
      document.getElementById('currentMnemonic').textContent = this.currentInstruction.mnemonic;
    } else {
      document.getElementById('currentOpcode').textContent = '--';
      document.getElementById('currentMnemonic').textContent = 'No instruction';
    }
  }
}

