            this.display[idx] ^= pixel ? 1 : 0;
          }
        }

        this.V[0xF] = collision;
        this.drawDisplay();
        mnemonic = `DRW V${this.hex(x)}, V${this.hex(y)}, ${height}`;
        break;

      case 0xE000:
        switch (kk) {
          case 0x9E:
            if (this.keys[this.V[x]] !== 0) this.pc += 2;
            mnemonic = `SKP V${this.hex(x)}`;
            break;
          case 0xA1:
            if (this.keys[this.V[x]] === 0) this.pc += 2;
            mnemonic = `SKNP V${this.hex(x)}`;
            break;
          default:
            mnemonic = 'UNKNOWN_EXNN';
        }
        break;

      case 0xF000:
        switch (n) {
          case 0x0:
            this.V[x] = this.delayTimer;
            mnemonic = `LD V${this.hex(x)}, DT`;
            break;
          case 0x1:
            this.V[x] = this.delayTimer;
            mnemonic = `LD V${this.hex(x)}, DT`;
            break;
          case 0x2:
            this.V[x] = this.soundTimer;
            mnemonic = `LD V${this.hex(x)}, ST`;
            break;
          case 0x3:
            const bcd = this.V[x];
            this.memory[this.I] = Math.floor(bcd / 100);
            this.memory[this.I + 1] = Math.floor((bcd % 100) / 10);
            this.memory[this.I + 2] = bcd % 10;
            mnemonic = `BCD V${this.hex(x)}`;
            break;
          case 0x4:
            for (let i = 0; i <= x; i++) {
              this.memory[this.I + i] = this.V[i];
            }
            mnemonic = `LD [I], V${this.hex(x)}`;
            break;
          case 0x5:
            for (let i = 0; i <= x; i++) {
              this.memory[this.I + i] = this.V[i];
            }
            mnemonic = `LD [I], V${this.hex(x)}`;
            break;
          case 0x6:
            for (let i = 0; i <= x; i++) {
              this.memory[this.I + i] = this.V[i];
            }
            mnemonic = `LD [I], V${this.hex(x)}`;
            break;
          case 0x7:
            this.V[x] = (this.V[x] + this.delayTimer) & 0xFF;
            mnemonic = `ADD V${this.hex(x)}, DT`;
            break;
          case 0x8:
            this.delayTimer = this.V[x];
            mnemonic = `LD DT, V${this.hex(x)}`;
            break;
          case 0x9:
            this.soundTimer = this.V[x];
            mnemonic = `LD ST, V${this.hex(x)}`;
            break;
          case 0xA:
            this.I = this.V[x] * 5;
            mnemonic = `LD F, V${this.hex(x)}`;
            break;
          case 0xB:
            this.I = this.V[x] * 5;
            mnemonic = `LD B, V${this.hex(x)}`;
            break;
          case 0xC:
            for (let i = 0; i <= x; i++) {
              this.memory[this.I + i] = this.V[i];
            }
            mnemonic = `LD [I], V${this.hex(x)}`;
            break;
          case 0xD:
            for (let i = 0; i <= x; i++) {
              this.memory[this.I + i] = this.V[i];
            }
            mnemonic = `LD [I], V${this.hex(x)}`;
            break;
          case 0xE:
            for (let i = 0; i <= x; i++) {
              this.memory[this.I + i] = this.V[i];
            }
            mnemonic = `LD [I], V${this.hex(x)}`;
            break;
          case 0xF:
            for (let i = 0; i <= x; i++) {
              this.memory[this.I + i] = this.V[i];
            }
            mnemonic = `LD [I], V${this.hex(x)}`;
            break;
          default:
            mnemonic = 'UNKNOWN_FXNN';
        }
        break;

      default:
        mnemonic = 'UNKNOWN';
    }

    this.currentInstruction = {
      opcode: opcode,
      mnemonic: mnemonic,
      x: x,
      y: y,
      n: n,
      nn: nn,
      nnn: nnn,
      kk: kk
    };
  }

  hex(val, digits = 2) {
    return '0x' + val.toString(16).toUpperCase().padStart(digits * 2, '0');
  }

  drawDisplay() {
    const canvas = document.getElementById('display');
    const ctx = canvas.getContext('2d');

    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#00ff88';
    for (let y = 0; y < 32; y++) {
      for (let x = 0; x < 64; x++) {
        if (this.display[y * 64 + x]) {
          ctx.fillRect(x * 10, y * 10, 10, 10);
        }
      }
    }
  }

  updateTimers() {
    if (this.delayTimer > 0) this.delayTimer--;
    if (this.soundTimer > 0) this.soundTimer--;
  }

  step() {
    if (!this.running && !this.waitingForKey) return;

    // If waiting for key, check if a key is pressed
    if (this.waitingForKey) {
      let keyFound = false;
      for (let i = 0; i < 16; i++) {
        if (this.keys[i] !== 0) {
          this.V[this.currentInstruction.x] = i;
          keyFound = true;
          this.waitingForKey = false;
          break;
        }
      }
      if (!keyFound) {
        // Don't advance PC, stay waiting
        return;
      }
    }

    this.fetchOpcode();
    this.decodeAndExecute(this.opcode);
    this.updateTimers();
    this.updateDebugger();
  }

  run() {
    this.running = true;
    this.waitingForKey = false;
    document.getElementById('status').innerHTML = '<span class="running">Running</span>';
    document.getElementById('runBtn').classList.add('active');
    document.getElementById('pauseBtn').classList.remove('active');
  }

  pause() {
    this.running = false;
    document.getElementById('status').innerHTML = '<span class="paused">Paused</span>';
    document.getElementById('runBtn').classList.remove('active');
    document.getElementById('pauseBtn').classList.add('active');
  }

  reset() {
    this.running = false;
    this.pc = 0x200;
    this.I = 0;
    this.V.fill(0);
    this.sp = 0;
    this.delayTimer = 0;
    this.soundTimer = 0;
    this.display.fill(0);
    this.keys.fill(0);
    this.opcode = 0;
    this.currentInstruction = null;
    this.waitingForKey = false;
    this.initDisplay();
    this.updateDebugger();
    document.getElementById('status').innerHTML = '<span class="paused">Paused</span>';
    document.getElementById('runBtn').classList.remove('active');
    document.getElementById('pauseBtn').classList.remove('active');
  }

  initDebuggerDisplay() {
    const registersEl = document.getElementById('registers');
    registersEl.innerHTML = '';

    for (let i = 0; i < 16; i++) {
      const regEl = document.createElement('div');
      regEl.className = 'debug-reg';
      const regNum = i.toString(16).toUpperCase();
      regEl.innerHTML = `
        <label>V${i}</label>
        <span id="regV${regNum}">0x00</span>
      `;
      registersEl.appendChild(regEl);
    }
  }

  updateDebugger() {
    for (let i = 0; i < 16; i++) {
      const regEl = document.getElementById(`regV${i.toString(16).toUpperCase()}`);
      if (regEl) {
        regEl.textContent = this.hex(this.V[i], 1);
      }
    }

    document.getElementById('indexReg').textContent = this.hex(this.I, 2);
    document.getElementById('programCounter').textContent = this.hex(this.pc, 2);

    const stackEl = document.getElementById('stack');
    if (this.sp === 0) {
      stackEl.innerHTML = '<span class="debug-stack-item">Empty</span>';
    } else {
      stackEl.innerHTML = this.stack.slice(0, this.sp).map(addr => 
        `<span class="debug-stack-item">${this.hex(addr, 2)}</span>`
      ).join('');
    }

    document.getElementById('delayTimer').textContent = this.delayTimer;
    document.getElementById('soundTimer').textContent = this.soundTimer;

    if (this.currentInstruction) {
      document.getElementById('currentOpcode').textContent = this.hex(this.opcode, 2);
      document.getElementById('currentMnemonic').textContent = this.currentInstruction.mnemonic;
    } else {
      document.getElementById('currentOpcode').textContent = '--';
      document.getElementById('currentMnemonic').textContent = 'No instruction';
    }
  }
}

// Initialize emulator
const emulator = new Chip8();
emulator.loadROM(DEMO_ROM);

// Set up keyboard display
function setupKeyboardDisplay() {
  const keyboardEl = document.getElementById('keyboard');
  keyboardEl.innerHTML = '';

  CHIP8_KEYS.forEach((row, rowIndex) => {
    row.forEach((key, colIndex) => {
      const chip8Key = rowIndex * 4 + colIndex;
      const keyEl = document.createElement('div');
      keyEl.className = 'key';
      keyEl.textContent = key;
      keyEl.dataset.chip8Key = chip8Key;
      keyEl.id = `key${chip8Key}`;
      keyboardEl.appendChild(keyEl);
    });
  });
}

// Handle keyboard events
document.addEventListener('keydown', (e) => {
  const chip8Key = Object.keys(KEY_MAP).find(k => KEY_MAP[k] === e.code);
  if (chip8Key !== undefined) {
    e.preventDefault();
    const keyIndex = parseInt(chip8Key);
    emulator.keys[keyIndex] = 1;
    document.getElementById(`key${keyIndex}`).classList.add('pressed');
  }
});

document.addEventListener('keyup', (e) => {
  const chip8Key = Object.keys(KEY_MAP).find(k => KEY_MAP[k] === e.code);
  if (chip8Key !== undefined) {
    const keyIndex = parseInt(chip8Key);
    emulator.keys[keyIndex] = 0;
    document.getElementById(`key${keyIndex}`).classList.remove('pressed');
  }
});

// Control functions
function toggleRun() {
  if (emulator.running) {
    emulator.pause();
  } else {
    emulator.run();
  }
}

function pause() {
  emulator.pause();
}

function singleStep() {
  emulator.pause();
  emulator.step();
}

function reset() {
  emulator.reset();
  emulator.loadROM(DEMO_ROM);
}

function loadROMFile(event) {
  const file = event.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = (e) => {
    const arrayBuffer = e.target.result;
    const romData = new Uint8Array(arrayBuffer);
    emulator.loadROM(romData);
    emulator.pause();
  };
  reader.readAsArrayBuffer(file);
}

function updateSpeed() {
  const speed = document.getElementById('speedSlider').value;
  document.getElementById('speedValue').textContent = speed;
  emulator.instrPerFrame = parseInt(speed);
}

// Main loop
function mainLoop() {
  if (emulator.running) {
    for (let i = 0; i < emulator.instrPerFrame; i++) {
      emulator.step();
    }
  }

  requestAnimationFrame(mainLoop);
}

// Initialize
setupKeyboardDisplay();
updateSpeed();
mainLoop();

console.log('CHIP-8 Emulator initialized');
console.log('Demo ROM loaded');
console.log('Controls: Run, Pause, Step, Reset, Load ROM');
console.log('Speed slider: Adjust instructions per frame');
console.log('Keyboard mapping:');
console.log('  X,1,2,3 | Q,W,E,A | S,D,Z,C | 4,R,F,V');
</script>
</body>
</html>
